WITH scored AS (SELECT *, AVG(balance) OVER w_hist AS running_avg_balance, SUM(balance) OVER w_hist AS running_sum_balance, MAX(balance) OVER w_hist AS running_max_balance, AVG(balance) OVER (PARTITION BY DATE_TRUNC('WEEK', opened_date) ORDER BY balance, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS balance_avg_5 FROM accounts WINDOW w_hist AS (PARTITION BY customer_id, status ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, customer_id, opened_date, status, running_avg_balance, running_sum_balance, balance_avg_5 FROM scored ORDER BY balance_avg_5, running_avg_balance DESC;
